interpolation_type.description:
Interpolation method for image transformations: 'none', 'linear', 'cubic', 'nohalo', 'lohalo'.
      "enum": [
        "none",
        "linear",
        "cubic",
        "nohalo",
        "lohalo"
      ]
    },
    "default_threshold": {
      "type": "number",
      "default": 15,
      "description": "Default threshold for region-filling tools (e.g., Fuzzy Select)."
    },
    "plug_in_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/plug-ins",
        "/usr/lib/gimp/2.0/plug-ins"
      ],
      "description": "Colon-separated list of directories to search for plug-ins."
    },
    "module_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/modules",
        "/usr/lib/gimp/2.0/modules"
      ],
      "description": "Colon-separated list of directories to search for GIMP modules (e.g., color management)."
    },
    "interpreter_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/interpreters",
        "/usr/lib/gimp/2.0/interpreters"
      ],
      "description": "Colon-separated list of directories to search for script interpreters (e.g., Python, Perl)."
    },
    "environ_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/environ",
        "/usr/lib/gimp/2.0/environ"
      ],
      "description": "Colon-separated list of directories to search for environment config files."
    },
    "brush_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/brushes",
        "/usr/share/gimp/2.0/brushes"
      ],
      "description": "Colon-separated list of directories to search for brushes."
    },
    "brush_path_writable": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/brushes"
      ],
      "description": "Colon-separated list of writable brush directories."
    },
    "dynamics_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/dynamics",
        "/usr/share/gimp/2.0/dynamics"
      ],
      "description": "Colon-separated list of directories to search for paint dynamics."
    },
    "dynamics_path_writable": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/dynamics"
      ],
      "description": "Colon-separated list of writable dynamics directories."
    },
    "mypaint_brush_path": {
      "type": "list",
      "default": [
        "/usr/share/mypaint-data/1.0/brushes",
        "~/.mypaint/brushes"
      ],
      "description": "Colon-separated list of directories to search for MyPaint brushes."
    },
    "mypaint_brush_path_writable": {
      "type": "list",
      "default": [
        "~/.mypaint/brushes"
      ],
      "description": "Colon-separated list of writable MyPaint brush directories."
    },
    "pattern_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/patterns",
        "/usr/share/gimp/2.0/patterns"
      ],
      "description": "Colon-separated list of directories to search for patterns."
    },
    "pattern_path_writable": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/patterns"
      ],
      "description": "Colon-separated list of writable pattern directories."
    },
    "palette_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/palettes",
        "/usr/share/gimp/2.0/palettes"
      ],
      "description": "Colon-separated list of directories to search for palettes."
    },
    "palette_path_writable": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/palettes"
      ],
      "description": "Colon-separated list of writable palette directories."
    },
    "gradient_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/gradients",
        "/usr/share/gimp/2.0/gradients"
      ],
      "description": "Colon-separated list of directories to search for gradients."
    },
    "gradient_path_writable": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/gradients"
      ],
      "description": "Colon-separated list of writable gradient directories."
    },
    "tool_preset_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/tool-presets",
        "/usr/share/gimp/2.0/tool-presets"
      ],
      "description": "Colon-separated list of directories to search for tool presets."
    },
    "tool_preset_path_writable": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/tool-presets"
      ],
      "description": "Colon-separated list of writable tool preset directories."
    },
    "font_path": {
      "type": "list",
      "default": [
        "~/.local/share/gimp/2.0/fonts",
        "/usr/share/fonts"
      ],
      "description": "Colon-separated list of directories to search for fonts (in addition to system fonts)."
    },
    "default_brush": {
      "type": "string",
      "default": "2. Hardness 050",
      "description": "Name of the default brush to select on startup."
    },
    "default_dynamics": {
      "type": "string",
      "default": "Dynamics Off",
      "description": "Name of the default paint dynamics."
    },
    "default_mypaint_brush": {
      "type": "string",
      "default": "Fixme",
      "description": "Name of the default MyPaint brush."
    },
    "default_pattern": {
      "type": "string",
      "default": "Pine",
      "description": "Name of the default pattern."
    },
    "default_palette": {
      "type": "string",
      "default": "Default",
      "description": "Name of the default palette."
    },
    "default_gradient": {
      "type": "string",
      "default": "FG to BG (RGB)",
      "description": "Name of the default gradient."
    },
    "default_tool_preset": {
      "type": "string",
      "default": "Current Options",
      "description": "Name of the default tool preset."
    },
    "default_font": {
      "type": "string",
      "default": "Sans-serif",
      "description": "Name of the default font."
    },
    "global_brush": {
      "type": "boolean",
      "default": true,
      "description": "Whether brush selection is global across tools."
    },
    "global_dynamics": {
      "type": "boolean",
      "default": true,
      "description": "Whether dynamics selection is global across tools."
    },
    "global_pattern": {
      "type": "boolean",
      "default": true,
      "description": "Whether pattern selection is global across tools."
    },
    "global_palette": {
      "type": "boolean",
      "default": true,
      "description": "Whether palette selection is global across tools."
    },
    "global_gradient": {
      "type": "boolean",
      "default": true,
      "description": "Whether gradient selection is global across tools."
    },
    "global_font": {
      "type": "boolean",
      "default": true,
      "description": "Whether font selection is global across tools."
    },
    "default_image": {
      "type": "object",
      "default": {
        "width": 1920,
        "height": 1080,
        "unit": "pixels",
        "xresolution": 300,
        "yresolution": 300,
        "resolution_unit": "inches",
        "image_type": "rgb",
        "precision": "u8-gamma",
        "color_managed": true,
        "color_profile": null,
        "fill_type": "background",
        "comment": "Created with GIMP"
      },
      "description": "Parameters for new images created via File > New."
    },
    "default_grid": {
      "type": "object",
      "default": {
        "style": "solid",
        "fgcolor": [
          0,
          0,
          0,
          1
        ],
        "bgcolor": [
          1,
          1,
          1,
          1
        ],
        "xspacing": 10,
        "yspacing": 10,
        "spacing_unit": "inches",
        "xoffset": 0,
        "yoffset": 0,
        "offset_unit": "inches"
      },
      "description": "Default grid appearance and spacing for new images."
    },
    "undo_levels": {
      "type": "number",
      "default": 5,
      "description": "Minimum number of undo steps to always keep."
    },
    "undo_size": {
      "type": "string",
      "default": "1G",
      "description": "Memory limit for undo history per image (K/M/G/B suffixes supported)."
    },
    "undo_preview_size": {
      "type": "string",
      "default": "large",
      "description": "Size of undo history previews: 'tiny', 'extra-small', 'small', 'medium', 'large', etc.",
      "enum": [
        "tiny",
        "extra-small",
        "small",
        "medium",
        "large",
        "extra-large",
        "huge",
        "enormous",
        "gigantic"
      ]
    },
    "plug_in_history_size": {
      "type": "number",
      "default": 10,
      "description": "Number of recent plug-ins to keep in the Filters menu."
    },
    "pluginrc_path": {
      "type": "string",
      "default": "~/.config/GIMP/2.10/pluginrc",
      "description": "Path to file storing plug-in registration cache."
    },
    "layer_previews": {
      "type": "boolean",
      "default": true,
      "description": "Whether to generate layer/channel previews in dialogs (impacts performance)."
    },
    "group_layer_previews": {
      "type": "boolean",
      "default": true,
      "description": "Whether to generate layer-group previews (expensive for large trees)."
    },
    "layer_preview_size": {
      "type": "string",
      "default": "medium",
      "description": "Preview size for layers/channels: 'tiny', 'small', 'medium', etc.",
      "enum": [
        "tiny",
        "extra-small",
        "small",
        "medium",
        "large",
        "extra-large",
        "huge",
        "enormous",
        "gigantic"
      ]
    },
    "thumbnail_size": {
      "type": "string",
      "default": "normal",
      "description": "Thumbnail size in open dialog: 'none', 'normal', 'large'.",
      "enum": [
        "none",
        "normal",
        "large"
      ]
    },
    "thumbnail_filesize_limit": {
      "type": "string",
      "default": "4M",
      "description": "Files smaller than this will have thumbnails regenerated on open."
    },
    "color_management": {
      "type": "object",
      "default": {
        "mode": "display",
        "display_profile_from_gdk": false,
        "display_rendering_intent": "relative-colorimetric",
        "display_use_black_point_compensation": true,
        "display_optimize": true,
        "simulation_rendering_intent": "perceptual",
        "simulation_use_black_point_compensation": false,
        "simulation_optimize": true,
        "simulation_gamut_check": false,
        "out_of_gamut_color": [
          1,
          0,
          1
        ],
        "show_rgb_u8": false,
        "show_hsv": false,
        "display_module": "CdisplayLcms"
      },
      "description": "Color management behavior (display, simulation, gamut warnings, etc.)."
    },
    "save_document_history": {
      "type": "boolean",
      "default": true,
      "description": "Whether to permanently record opened/saved files in Recent Documents."
    },
    "quick_mask_color": {
      "type": "list",
      "default": [
        1,
        0,
        0,
        0.5
      ],
      "description": "RGBA color for quick mask overlay (red, green, blue, alpha in 0–1 range)."
    },
    "import_promote_float": {
      "type": "boolean",
      "default": false,
      "description": "Whether to promote imported images to floating-point precision."
    },
    "import_promote_dither": {
      "type": "boolean",
      "default": true,
      "description": "Whether to add noise when promoting to floating-point precision."
    },
    "import_add_alpha": {
      "type": "boolean",
      "default": false,
      "description": "Whether to add alpha channel to layers of imported images."
    },
    "import_raw_plug_in": {
      "type": "string",
      "default": "",
      "description": "Plug-in name used to import raw camera files (e.g., 'darkroom')."
    },
    "export_file_type": {
      "type": "string",
      "default": "png",
      "description": "Default file format for export: 'png', 'jpg', 'ora', etc.",
      "enum": [
        "png",
        "jpg",
        "ora",
        "psd",
        "pdf",
        "tif",
        "bmp",
        "webp"
      ]
    },
    "export_color_profile": {
      "type": "boolean",
      "default": true,
      "description": "Whether to embed image color profile during export."
    },
    "export_metadata_exif": {
      "type": "boolean",
      "default": true,
      "description": "Whether to export Exif metadata by default."
    },
    "export_metadata_xmp": {
      "type": "boolean",
      "default": true,
      "description": "Whether to export XMP metadata by default."
    },
    "export_metadata_iptc": {
      "type": "boolean",
      "default": true,
      "description": "Whether to export IPTC metadata by default."
    },
    "debug_policy": {
      "type": "string",
      "default": "fatal",
      "description": "Debug output policy: 'never', 'warning', 'critical', 'fatal'.",
      "enum": [
        "never",
        "warning",
        "critical",
        "fatal"
      ]
    },
    "check_updates": {
      "type": "boolean",
      "default": true,
      "description": "Whether to automatically check for GIMP updates in background."
    },
    "transparency_size": {
      "type": "string",
      "default": "medium-checks",
      "description": "Checker size for transparency: 'small-checks', 'medium-checks', 'large-checks'.",
      "enum": [
        "small-checks",
        "medium-checks",
        "large-checks"
      ]
    },
    "transparency_type": {
      "type": "string",
      "default": "gray-checks",
      "description": "Checker pattern for transparency: 'light-checks', 'gray-checks', etc.",
      "enum": [
        "light-checks",
        "gray-checks",
        "dark-checks",
        "white-only",
        "gray-only",
        "black-only"
      ]
    },
    "snap_distance": {
      "type": "number",
      "default": 8,
      "description": "Distance (pixels) where guides/grids snap to cursor."
    },
    "marching_ants_speed": {
      "type": "number",
      "default": 200,
      "description": "Speed of selection outline animation (ms — lower = faster)."
    },
    "resize_windows_on_zoom": {
      "type": "boolean",
      "default": false,
      "description": "Whether to resize image window when zoom changes (multi-window mode only)."
    },
    "resize_windows_on_resize": {
      "type": "boolean",
      "default": false,
      "description": "Whether to resize image window when physical image size changes (multi-window mode)."
    },
    "default_show_all": {
      "type": "boolean",
      "default": false,
      "description": "Whether new images are shown fully fitted by default."
    },
    "default_dot_for_dot": {
      "type": "boolean",
      "default": true,
      "description": "Whether to map one image pixel to one screen pixel by default."
    },
    "initial_zoom_to_fit": {
      "type": "boolean",
      "default": true,
      "description": "Whether to fit image to window on file open (else 1:1 view)."
    },
    "cursor_mode": {
      "type": "string",
      "default": "tool-crosshair",
      "description": "Mouse cursor style: 'tool-icon', 'tool-crosshair', 'crosshair'.",
      "enum": [
        "tool-icon",
        "tool-crosshair",
        "crosshair"
      ]
    },
    "cursor_updating": {
      "type": "boolean",
      "default": true,
      "description": "Whether to update context-sensitive cursor overlays."
    },
    "show_brush_outline": {
      "type": "boolean",
      "default": true,
      "description": "Whether to draw brush outline preview while painting."
    },
    "snap_brush_outline": {
      "type": "boolean",
      "default": false,
      "description": "Whether brush outline snaps to individual dabs."
    },
    "show_paint_tool_cursor": {
      "type": "boolean",
      "default": true,
      "description": "Whether to show cursor over image during paint operations."
    },
    "image_title_format": {
      "type": "string",
      "default": "%D*%f-%p.%i (%t, %o, %L) %wx%h",
      "description": "Format string for image window titles (supports %f, %D, %t, etc.)."
    }
  },
